//! The tmux that `terminus server tmux` installs, built from source at this
//! commit: tmux 3.5a over libevent 2.1.12 (core only) and ncurses 6.5 (tinfo
//! only), cross-compiled to static x86_64-linux-musl.
//!
//! No autoconf runs here. The three configure scripts were run once against
//! `zig cc -target x86_64-linux-musl`, and what they produced is vendored:
//! `libevent/config.h` and `libevent/include/event2/event-config.h`, ncurses'
//! generated headers and sources (`ncurses_cfg.h`, `names.c`, `codes.c`, ...),
//! and tmux's `-D` list below, copied from its Makefile. The source lists are
//! the object lists those builds actually linked.
//!
//! `ncurses/ncurses/fallback.c` is the part that matters most. It is the
//! terminfo for xterm-256color, xterm, screen, screen-256color, tmux,
//! tmux-256color, vt100, ansi and dumb, compiled into the binary: a host with
//! no `/usr/share/terminfo` still starts a session. ncurses reads the system
//! database first and only falls back to these, so a host that has a better
//! entry keeps it.

const std = @import("std");

pub fn add(b: *std.Build) *std.Build.Step.Compile {
    const target = b.resolveTargetQuery(.{
        .cpu_arch = .x86_64,
        .os_tag = .linux,
        .abi = .musl,
    });
    const mod = b.createModule(.{
        .target = target,
        // Small for the same reason as the helper: it is embedded in the CLI
        // and sent over the network. Stripped for the same reason.
        .optimize = .small,
        .link_libc = true,
        .strip = true,
    });

    mod.addCSourceFiles(.{
        .root = b.path("vendor/libevent"),
        .files = &libevent_sources,
        .flags = &.{ "-DHAVE_CONFIG_H", "-fno-sanitize=undefined" },
    });
    mod.addIncludePath(b.path("vendor/libevent"));
    mod.addIncludePath(b.path("vendor/libevent/compat"));
    mod.addIncludePath(b.path("vendor/libevent/include"));

    mod.addCSourceFiles(.{
        .root = b.path("vendor/ncurses/ncurses"),
        .files = &ncurses_sources,
        .flags = &.{
            "-DHAVE_CONFIG_H",
            "-DBUILDING_NCURSES",
            "-DNDEBUG",
            "-DNCURSES_STATIC",
            "-DUSE_TERMLIB",
            "-fno-sanitize=undefined",
        },
    });
    mod.addIncludePath(b.path("vendor/ncurses/ncurses"));
    mod.addIncludePath(b.path("vendor/ncurses/include"));

    mod.addCSourceFiles(.{
        .root = b.path("vendor/tmux"),
        .files = &tmux_sources,
        .flags = &tmux_flags,
    });
    mod.addIncludePath(b.path("vendor/tmux"));

    return b.addExecutable(.{
        .name = "tmux",
        .root_module = mod,
        .linkage = .static,
    });
}

